DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_enqueue(uuid,date,text,text,text,text,jsonb,jsonb,text,uuid)'::regprocedure) INTO def;IF position('IF NOT public.finance_schedule_manager(t)' IN def)=0 THEN RAISE EXCEPTION 'Draft permission anchor unavailable';END IF;def:=replace(def,'IF NOT public.finance_schedule_manager(t)','IF NOT (public.finance_schedule_manager(t) OR k=''account_reclass'' AND public.finance_can_merge_accounts(t))');EXECUTE def;END $$;